begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000000901','internal-owner@test.local'),('00000000-0000-0000-0000-000000000902','internal-outsider@test.local');
insert into public.companies(id,legal_name,display_name,created_by) values('10000000-0000-0000-0000-000000000901','Internal','Internal','00000000-0000-0000-0000-000000000901');
insert into public.company_memberships(company_id,user_id,role) values('10000000-0000-0000-0000-000000000901','00000000-0000-0000-0000-000000000901','owner');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000901';
select lives_ok($$select public.save_transaction('10000000-0000-0000-0000-000000000901',null,null,'income',current_date,'Customer','Internal receipt',100,'posted',null,null,'20000000-0000-0000-0000-000000000901')$$,'paid income posts');
select is((select sum(credit) from public.journal_lines where company_id='10000000-0000-0000-0000-000000000901'),100::numeric,'income journal has expected credits');
select is((select sum(debit-credit) from public.journal_lines where company_id='10000000-0000-0000-0000-000000000901'),0::numeric,'income journal balances');
select lives_ok($$select public.save_transaction('10000000-0000-0000-0000-000000000901',null,null,'income',current_date,'Customer','Internal receipt',100,'posted',null,null,'20000000-0000-0000-0000-000000000901')$$,'lost response retry succeeds');
select is((select count(*) from public.income where company_id='10000000-0000-0000-0000-000000000901'),1::bigint,'retry creates no duplicate');
select throws_ok($$select public.save_transaction('10000000-0000-0000-0000-000000000901',null,null,'income',current_date,'Customer','Internal receipt',101,'posted',null,null,'20000000-0000-0000-0000-000000000901')$$,'P0001','Request ID was already used with different details','changed retry rejected');
select throws_ok($$update public.income set amount=50 where company_id='10000000-0000-0000-0000-000000000901'$$,'P0001','Posted records must be reversed, not edited','posted source immutable');
select throws_ok($$delete from public.income where company_id='10000000-0000-0000-0000-000000000901'$$,'P0001','Posted records must be reversed, not deleted','posted source cannot be deleted');
select lives_ok($$select public.reverse_money_record('10000000-0000-0000-0000-000000000901','income',(select id from public.income where company_id='10000000-0000-0000-0000-000000000901'),current_date,'Correction')$$,'source correction posts a reversal');
select lives_ok($$select public.reverse_money_record('10000000-0000-0000-0000-000000000901','income',(select id from public.income where company_id='10000000-0000-0000-0000-000000000901'),current_date,'Correction')$$,'reversal retry succeeds');
select is((select count(*) from public.journal_entries where company_id='10000000-0000-0000-0000-000000000901'),2::bigint,'reversal retry creates no duplicate journal');
select is((select sum(debit-credit) from public.journal_lines l join public.chart_of_accounts a on a.id=l.account_id where l.company_id='10000000-0000-0000-0000-000000000901' and a.account_number='1000'),0::numeric,'reversal clears cash movement');
select throws_ok($$update public.chart_of_accounts set account_type='expense' where company_id='10000000-0000-0000-0000-000000000901' and account_number='1000'$$,'P0001','Used account numbers and types cannot be changed','used account type is locked');
select lives_ok($$select public.set_accounting_period_closed('10000000-0000-0000-0000-000000000901',current_date-10,current_date-1,true)$$,'owner closes completed period');
select throws_ok($$select public.save_transaction('10000000-0000-0000-0000-000000000901',null,null,'expense',current_date-2,'Vendor','Closed period',50,'posted')$$,'P0001','Accounting period is closed','closed period blocks posting atomically');
select is((select count(*) from public.expenses where company_id='10000000-0000-0000-0000-000000000901'),0::bigint,'failed posting leaves no expense');
select lives_ok($$select public.set_accounting_period_closed('10000000-0000-0000-0000-000000000901',current_date-10,current_date-1,false)$$,'owner reopens period');
select lives_ok($$select public.save_invoice('10000000-0000-0000-0000-000000000901',null,'Invoice customer',current_date,current_date,'sent','','[{"description":"Freight","quantity":1,"unitPrice":100,"taxRate":0}]'::jsonb)$$,'issued invoice posts');
select lives_ok($$select public.record_invoice_payment('10000000-0000-0000-0000-000000000901',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000901'),current_date,100,(select id from public.chart_of_accounts where company_id='10000000-0000-0000-0000-000000000901' and account_number='1000'),'Received','20000000-0000-0000-0000-000000000902')$$,'invoice payment posts');
select lives_ok($$select public.record_customer_payment_adjustment('10000000-0000-0000-0000-000000000901',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000901'),(select id from public.payments where company_id='10000000-0000-0000-0000-000000000901'),'reversal',current_date,100,'Returned payment',(select id from public.chart_of_accounts where company_id='10000000-0000-0000-0000-000000000901' and account_number='1000'),'20000000-0000-0000-0000-000000000903')$$,'payment reversal posts');
select is((select status from public.invoices where company_id='10000000-0000-0000-0000-000000000901'),'sent','reversal reopens invoice');
select lives_ok($$select public.record_customer_payment_adjustment('10000000-0000-0000-0000-000000000901',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000901'),(select id from public.payments where company_id='10000000-0000-0000-0000-000000000901'),'reversal',current_date,100,'Returned payment',(select id from public.chart_of_accounts where company_id='10000000-0000-0000-0000-000000000901' and account_number='1000'),'20000000-0000-0000-0000-000000000903')$$,'payment correction retries safely');
select is((select count(*) from public.customer_payment_adjustments where company_id='10000000-0000-0000-0000-000000000901'),1::bigint,'one correction persists');
select lives_ok($$select public.record_invoice_payment('10000000-0000-0000-0000-000000000901',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000901'),current_date,100,(select id from public.chart_of_accounts where company_id='10000000-0000-0000-0000-000000000901' and account_number='1000'),'Replacement','20000000-0000-0000-0000-000000000904')$$,'reversed payment can be replaced');
select lives_ok($$select public.record_invoice_credit('10000000-0000-0000-0000-000000000901',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000901'),current_date,50,'Customer credit','20000000-0000-0000-0000-000000000905')$$,'paid invoice can receive credit');
select lives_ok($$select public.record_customer_payment_adjustment('10000000-0000-0000-0000-000000000901',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000901'),null,'refund',current_date,50,'Refund credit',(select id from public.chart_of_accounts where company_id='10000000-0000-0000-0000-000000000901' and account_number='1000'),'20000000-0000-0000-0000-000000000906')$$,'customer credit refund posts');
select throws_ok($$select public.record_customer_payment_adjustment('10000000-0000-0000-0000-000000000901',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000901'),null,'refund',current_date,1,'Excess refund',(select id from public.chart_of_accounts where company_id='10000000-0000-0000-0000-000000000901' and account_number='1000'),'20000000-0000-0000-0000-000000000907')$$,'P0001','Refund exceeds available customer credit','refund cannot exceed credit');
select is((select sum(debit-credit) from public.journal_lines l join public.chart_of_accounts a on a.id=l.account_id where l.company_id='10000000-0000-0000-0000-000000000901' and a.account_number='1100'),0::numeric,'refunded invoice reconciles to receivables control');
select is((select count(*) from public.audit_logs where company_id='10000000-0000-0000-0000-000000000901' and record_type='customer_payment_adjustments'),2::bigint,'customer corrections are audited');
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000902';
select throws_ok($$select public.manage_ledger_account('10000000-0000-0000-0000-000000000901',null,'5999','Bad account','expense',true)$$,'P0001','Accounting access required','outsider cannot manage accounts');
select is((select count(*) from public.customer_payment_adjustments),0::bigint,'outsider cannot read payment corrections');
select * from finish();
rollback;
